# This code has been fully generated by an AI.
"""Wer verbunden ist und in welcher Rolle: Moderation, Bühne oder Spieler 1/2.

Sitzungen und Spieler liegen in data/lobby.json, damit Clients nach einem Server-Neustart oder einem
Netzaussetzer ohne neue Anmeldung weitermachen.
"""

import hmac
import json
import logging
import secrets
import threading
import uuid
from pathlib import Path

log = logging.getLogger(__name__)

RESERVED = ("stage", "mod", "moderator")
MAX_NAME = 24
ROLE_LABEL = {"stage": "Bühne", "moderator": "Moderation", "player": "Spieler"}


class LobbyError(Exception):
    """Klartext für den Client; code sagt ihm, wie es weitergeht (z. B. „full“ → als Bühne anbieten)."""

    def __init__(self, message: str, code: str = "invalid"):
        super().__init__(message)
        self.code = code


class Lobby:
    def __init__(self, path: Path | None, password: str):
        self.path = path
        self.password = password
        self.server_id = uuid.uuid4().hex
        # token → {"role", "name"}; bei Spielern ist name der Schlüssel in players.
        self.sessions: dict[str, dict] = {}
        # name.lower() → {"name", "token", "slot"}; slot None heißt: bekannt, aber gerade nicht im Spiel.
        self.players: dict[str, dict] = {}
        self.online: dict[str, int] = {}
        self._lock = threading.Lock()
        self._load()

    # ---------- Anmeldung ----------

    def join(self, name: str, password: str = "", token: str = "") -> dict:
        name = str(name or "").strip()
        key = name.lower()
        with self._lock:
            if not name:
                raise LobbyError("Bitte einen Namen eingeben.")
            if key == "stage":
                token = self._session(token, "stage", "stage")
                result = {"role": "stage", "name": "stage", "slot": None}
            elif key in ("mod", "moderator"):
                if not hmac.compare_digest(str(password).encode(), self.password.encode()):
                    raise LobbyError("Falsches Passwort.", "password")
                token = self._session(token, "moderator", "moderator")
                result = {"role": "moderator", "name": "moderator", "slot": None}
            else:
                token, slot = self._join_player(name, key, token)
                name = self.players[key]["name"]
                result = {"role": "player", "name": name, "slot": slot}
            self._save()
        return {"token": token, **result}

    def _join_player(self, name: str, key: str, token: str) -> tuple[str, int]:
        if len(name) > MAX_NAME:
            raise LobbyError(f"Der Name darf höchstens {MAX_NAME} Zeichen haben.")
        record = self.players.get(key)
        mine = bool(record and token and record["token"] == token)
        if record and record["slot"] and not mine:
            raise LobbyError(f"„{record['name']}“ spielt schon als Spieler {record['slot']}. "
                             "Bitte einen anderen Namen wählen.", "taken")
        slot = record["slot"] if record and record["slot"] else None
        # Dasselbe Gerät mit neuem Namen: Umbenennen statt einen zweiten Platz zu belegen.
        renamed = next((r for k, r in self.players.items() if k != key and r["slot"] and token
                        and r["token"] == token), None)
        if slot is None and renamed is not None:
            slot, renamed["slot"] = renamed["slot"], None
        if slot is None:
            taken = {r["slot"] for r in self.players.values()}
            slot = next((s for s in (1, 2) if s not in taken), None)
        if slot is None:
            raise LobbyError("Beide Spielerplätze sind belegt.", "full")
        if not (token and self.sessions.get(token, {}).get("role") == "player"):
            token = secrets.token_urlsafe(18)
        old = self.sessions.get(record["token"]) if record else None
        if record and record["token"] != token and old and old["name"] == key:
            # Neues Gerät übernimmt den gespeicherten Namen; das alte handelt nicht mehr als dieser Spieler.
            self.sessions.pop(record["token"], None)
        self.players[key] = {"name": name, "token": token, "slot": slot}
        self.sessions[token] = {"role": "player", "name": key}
        return token, slot

    def _session(self, token: str, role: str, name: str) -> str:
        if not (token and self.sessions.get(token, {}).get("role") == role):
            token = secrets.token_urlsafe(18)
        self.sessions[token] = {"role": role, "name": name}
        return token

    def leave(self, token: str) -> int | None:
        """Spieler gibt seinen Platz frei; Name und Sitzung bleiben für eine spätere Rückkehr."""
        with self._lock:
            record = self._player(token)
            if record is None or not record["slot"]:
                return None
            slot, record["slot"] = record["slot"], None
            self._save()
            return slot

    def kick(self, slot: int) -> str | None:
        with self._lock:
            record = next((r for r in self.players.values() if r["slot"] == slot), None)
            if record is None:
                return None
            record["slot"] = None
            self._save()
            return record["name"]

    # ---------- Abfragen ----------

    def session(self, token: str | None) -> dict | None:
        """Rolle zum Token; Spieler bekommen ihren aktuellen Platz (None, wenn entfernt)."""
        with self._lock:
            found = self.sessions.get(token or "")
            if found is None:
                return None
            if found["role"] != "player":
                return dict(found)
            record = self._player(token)
            return {"role": "player", "name": record["name"] if record else found["name"],
                    "slot": record["slot"] if record else None}

    def describe(self, token: str | None) -> str:
        found = self.session(token)
        if found is None:
            return "Unbekannt"
        if found["role"] == "player":
            where = f"Spieler {found['slot']}" if found["slot"] else "Spieler ohne Platz"
            return f"{where} „{found['name']}“"
        return ROLE_LABEL[found["role"]]

    def connected(self, token: str, delta: int) -> None:
        with self._lock:
            count = self.online.get(token, 0) + delta
            if count > 0:
                self.online[token] = count
            else:
                self.online.pop(token, None)

    def public(self) -> dict:
        with self._lock:
            players = [{"slot": r["slot"], "name": r["name"], "online": r["token"] in self.online}
                       for r in self.players.values() if r["slot"]]
            counts = {"stage": 0, "moderator": 0, "player": 0}
            for token, n in self.online.items():
                role = self.sessions.get(token, {}).get("role")
                if role in counts:
                    counts[role] += n
        return {"players": sorted(players, key=lambda p: p["slot"]), "online": counts}

    def _player(self, token: str | None) -> dict | None:
        found = self.sessions.get(token or "")
        if not found or found["role"] != "player":
            return None
        record = self.players.get(found["name"])
        return record if record and record["token"] == token else None

    # ---------- Speicher ----------

    def _load(self) -> None:
        if self.path is None or not self.path.is_file():
            return
        try:
            data = json.loads(self.path.read_text("utf-8"))
            self.server_id = str(data.get("server_id") or self.server_id)
            self.sessions = dict(data.get("sessions", {}))
            self.players = dict(data.get("players", {}))
        except (OSError, ValueError, AttributeError):
            log.warning("%s ist unlesbar; alle Clients müssen sich neu anmelden.", self.path)

    def _save(self) -> None:
        if self.path is None:
            return
        self.path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.path.with_suffix(".tmp")
        data = {"server_id": self.server_id, "sessions": self.sessions, "players": self.players}
        tmp.write_text(json.dumps(data, ensure_ascii=False, indent=1), "utf-8")
        tmp.replace(self.path)
